INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine GUI immer benutzerfreundlicher als eine CLI?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Nutzer und Aufgabe"}, {"text": "Ja", "correct": false, "because": "CLI kann für Experten effizienter sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich primär mit einer GUI?', 3, '[{"text": "Intuitive Bedienung", "correct": true, "because": "Fördert Nutzerakzeptanz"}, {"text": "Maximale Performance", "correct": false, "because": "Sekundär"}, {"text": "Minimaler Speicher", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente machen eine GUI effektiv?', 5, '[{"text": "Konsistentes Design", "correct": true, "because": "Erleichtert Navigation"}, {"text": "Reaktionsschnelligkeit", "correct": true, "because": "Verbessert Nutzererlebnis"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hardware-aspekt"}, {"text": "Text-only-Modus", "correct": false, "because": "CLI-Feature"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) GUIs brauchen mehr Ressourcen als CLIs. b) Sie sind immer plattformabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Web-GUIs können plattformunabhängig sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Gestaltung einer GUI für mobile Apps?', 4, '[{"text": "Touch-Optimierung", "correct": false, "because": "Kern der Bedienung"}, {"text": "Responsive Design", "correct": false, "because": "Passt an Bildschirme"}, {"text": "Server-RAID-Level", "correct": true, "because": "Backend-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine GUI auch ohne Maus bedienbar sein sollte?', 2, '[{"text": "Ja", "correct": true, "because": "Tastaturnavigation ist Standard"}, {"text": "Nein", "correct": false, "because": "Barrierefreiheit ignoriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Framework wähle ich für eine Desktop-GUI?', 3, '[{"text": "Qt", "correct": true, "because": "Plattformübergreifend und flexibel"}, {"text": "Apache", "correct": false, "because": "Webserver, kein GUI-Tool"}, {"text": "Bash", "correct": false, "because": "CLI-Skripting"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei einer Web-GUI entscheidend?', 5, '[{"text": "Cross-Browser-Kompatibilität", "correct": true, "because": "Breite Nutzbarkeit"}, {"text": "Responsive Layouts", "correct": true, "because": "Passt an Geräte"}, {"text": "Statische IPs", "correct": false, "because": "Netzwerkaspekt"}, {"text": "Hohe CPU-Taktung", "correct": false, "because": "Hardware-seitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) GUIs sind nur für Anfänger. b) Sie verzögern die Entwicklung. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "GUIs für alle, Entwicklung abhängig"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide sind falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine GUI auf Mobilgeräten?', 4, '[{"text": "Touch-Gesten", "correct": false, "because": "Kern der Interaktion"}, {"text": "Skalierbare Schrift", "correct": false, "because": "Passt an Bildschirme"}, {"text": "CLI-Befehle", "correct": true, "because": "Nicht GUI-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine GUI immer interaktiv?', 2, '[{"text": "Ja", "correct": true, "because": "Interaktion ist Kernmerkmal"}, {"text": "Nein", "correct": false, "because": "Statische GUIs selten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien nutze ich für eine Web-GUI?', 4, '[{"text": "HTML/CSS", "correct": true, "because": "Grundlage der Darstellung"}, {"text": "JavaScript", "correct": true, "because": "Interaktivität ermöglichen"}, {"text": "SQL", "correct": false, "because": "Nur Backend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass GUIs immer mehr Ressourcen als CLIs brauchen. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Grafische Elemente erhöhen Bedarf"}, {"text": "Nein", "correct": false, "because": "Minimalistische GUIs möglich, aber selten"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer GUI für Endnutzer?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Fördert Akzeptanz"}, {"text": "Maximale Effizienz", "correct": false, "because": "Sekundär"}, {"text": "Minimaler Code", "correct": false, "because": "Entwicklungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mobile GUIs brauchen Touch-Optimierung. b) Desktop-GUIs sind für Server besser.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Server nutzen oft CLI"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Design-Prinzipien verbessern eine GUI?', 5, '[{"text": "Klarheit", "correct": true, "because": "Erleichtert Verständnis"}, {"text": "Konsistenz", "correct": true, "because": "Vermeidet Verwirrung"}, {"text": "Hohe Latenz", "correct": false, "because": "Verschlechtert Erfahrung"}, {"text": "Statische Layouts", "correct": false, "because": "Unflexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer GUI für Webseiten unwichtig?', 3, '[{"text": "Responsive Design", "correct": false, "because": "Passt an Geräte"}, {"text": "Browser-Kompatibilität", "correct": false, "because": "Sichert Nutzbarkeit"}, {"text": "Terminal-Befehle", "correct": true, "because": "CLI-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit GUIs? Sind sie für Automatisierung geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "CLI besser für Skripte"}, {"text": "Ja", "correct": false, "because": "Interaktivität im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine GUI auch für Experten nützlich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Visualisierung hilft oft"}, {"text": "Nein", "correct": false, "because": "Nicht nur für Anfänger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für eine mobile GUI?', 4, '[{"text": "Flutter", "correct": true, "because": "Plattformübergreifend und schnell"}, {"text": "Notepad", "correct": false, "because": "Nur Editor"}, {"text": "Ping", "correct": false, "because": "Netzwerktool"}]');
